export const AMIRI_REGULAR_BASE64: string = AMIRI_REGULAR_PARTS.join('')

export const amiriRegularFontBytes = (): Uint8Array => {
  const bin = typeof Buffer !== 'undefined'
    ? Buffer.from(AMIRI_REGULAR_BASE64, 'base64')
    : Uint8Array.from(atob(AMIRI_REGULAR_BASE64), (c) => c.charCodeAt(0))
  return new Uint8Array(bin)
}
